  function evidenceList(i) {
    return i.evidence.length ? '<section class="panel">' + i.evidence.map(rec => '<div class="evidence-card"><details data-evidence="' + rec.id + '"><summary><div><span class="mono blue">' + rec.id + '</span> <span style="font-size:11px">' + e(rec.capability) + '</span><div class="muted" style="font-size:9px;margin-top:5px">' + e(rec.host + ' · ' + rec.executor) + ' · ' + time(rec.at) + '</div></div><span class="row">' + badge(rec.redacted ? 'Redacted' : 'Read-only', rec.redacted ? 'amber' : 'green') + ico('down', 12) + '</span></summary><pre>' + e(rec.body) + '</pre><p class="hash mono">SHA-256 ' + rec.hash + '</p><p class="hash mt10">Caller: argus-worker · append-only evidence · policy verdict: allowed</p></details></div>').join('') + '</section>' : empty('Collecting evidence', 'The next bounded reads will appear here with their host, executor, and hash.', 'search');
  }
  function approvalSummary(i, inModal = false) {
    const p = i.proposal;
    if (!p) return '<div class="note amber">' + e(i.recommendation) + '</div>';
    return '<div class="proposal-card"><div class="proposal-title"><span class="host-symbol">' + ico('shield', 20) + '</span><div><h2>Proposed remediation</h2><p class="panel-sub">One immutable action. One human decision.</p></div></div><div class="proposal-command mono">' + e(p.capability) + ' → ' + e(p.target.split(':').at(-1)) + '</div><div class="kv"><span>Host / target identity</span><span class="mono">' + i.host + ' / ' + p.identity + '</span></div><div class="kv"><span>Arguments</span><span class="mono">timeout_seconds: 10</span></div><div class="kv"><span>Risk / permitted attempts</span><span>' + badge('Medium', 'amber') + ' · one action</span></div><div class="kv"><span>Evidence version / records</span><span>v' + p.evidenceVersion + ' / ' + p.evidenceIds.length + ' citations</span></div><div class="kv"><span>Approval</span><span>' + badge(i.approval.state, i.approval.state === 'approved' ? 'green' : i.approval.state === 'pending' ? 'amber' : 'red') + '</span></div>' + (i.approval.state === 'pending' ? '<div class="kv"><span>Expires in</span><span>' + remaining(p) + '</span></div>' : '<div class="kv"><span>Decision actor</span><span>' + e(i.approval.actor || 'System') + '</span></div>') + '<div class="mt10 hash mono">proposal ' + e(p.id) + '<br>SHA-256 ' + p.digest + '<br>policy ' + p.policyVersion.slice(0, 20) + '… · inventory v1</div><div class="note amber mt" style="font-size:10px">Cache contents may be lost. ' + e(p.rollback) + '</div>' + (i.approval.state === 'pending' && i.status === 'awaiting_approval' ? inModal ? '<label class="field-label mt" for="approval-note">Decision note <span class="muted">(optional)</span></label><textarea class="field" id="approval-note" rows="2" placeholder="Reason for this decision..."></textarea><div class="note mt10" style="font-size:10px">' + (sim.canApprove && sim.principal.scopes.includes(i.host) ? 'You are deciding as ' + e(sim.principal.name) + ', a human approver scoped to ' + i.host + '.' : 'Current principal cannot approve this target. Switch to an in-scope human approver to make a decision.') + '</div><div class="approval-actions">' + btn('Deny action', 'deny', 'data-id="' + i.id + '"', 'danger', 'x', sim.canApprove && sim.principal.scopes.includes(i.host) ? '' : 'disabled') + btn('Approve one restart', 'approve', 'data-id="' + i.id + '"', 'primary', 'check', sim.canApprove && sim.principal.scopes.includes(i.host) ? '' : 'disabled') + '</div>' : '<div class="approval-actions">' + btn('Review & decide', 'review', 'data-id="' + i.id + '"', 'primary full', 'shield') + '</div>' : '') + '</div>';
  }
