    return pageHead('Human approvals', 'Argus proposes. An authenticated human decides. Current state is checked again before execution.', btn('Switch identity', 'identity', '', 'ghost', 'user')) + '<div class="note mb">' + ico('shield', 15) + '<p class="mt10">A decision binds to an exact proposal digest, target identity, evidence version and policy. Service and peer-agent identities never hold approval authority.</p></div>' + (pending.length ? '<div class="host-grid mb">' + pending.map(i => '<section class="panel approval-card"><div class="panel-header"><div><h2>' + i.id + ' · ' + e(i.title) + '</h2><p class="panel-sub">' + e(i.target) + '</p></div>' + badge('Pending', 'amber') + '</div>' + approvalSummary(i) + '</section>').join('') + '</div>' : '<section class="panel mb">' + empty('No decisions waiting', 'New proposals appear here only when a write pair is released and policy permits it.', 'shield', btn('Create a cache failure', 'quick-cache', '', 'primary', 'plus')) + '</section>') + summaryPanel('Decision history', history.length ? '<div class="table-scroll"><table><thead><tr><th>Incident</th><th>Decision</th><th>Actor</th><th>Action result</th><th></th></tr></thead><tbody>' + history.map(i => '<tr class="clickable" data-action="incident" data-id="' + i.id + '"><td>' + i.id + '<span class="sub">' + e(i.title) + '</span></td><td>' + badge(i.approval.state, i.approval.state === 'approved' ? 'green' : 'red') + '</td><td>' + e(i.approval.actor || 'System') + '</td><td>' + e(i.action?.state || 'No dispatch') + '</td><td>' + ico('right', 13) + '</td></tr>').join('') + '</tbody></table></div>' : '<div class="panel-body muted" style="font-size:11px">Your approval, denial, expiry and cancellation decisions will appear here.</div>') + footer();
